internal static class FirebirdOutputText {
    public static readonly Encoding Encoding = System.Text.Encoding.GetEncoding(65001, EncoderFallback.ReplacementFallback, new Windows1252DecoderFallback());
}
internal sealed class Windows1252DecoderFallback : DecoderFallback {
    public override int MaxCharCount { get { return 8; } }
    public override DecoderFallbackBuffer CreateFallbackBuffer() { return new Windows1252DecoderFallbackBuffer(); }
}
internal sealed class Windows1252DecoderFallbackBuffer : DecoderFallbackBuffer {
    static readonly System.Text.Encoding Windows1252 = System.Text.Encoding.GetEncoding(1252);
    string pending = "";
    int position;
    public override bool Fallback(byte[] bytesUnknown, int index) {
        if (Remaining > 0) throw new ArgumentException("O buffer de fallback ainda contém caracteres.");
        pending = Windows1252.GetString(bytesUnknown);
        position = 0;
        return pending.Length > 0;
    }
    public override char GetNextChar() { if (position >= pending.Length) return '\0'; return pending[position++]; }
    public override bool MovePrevious() { if (position <= 0) return false; position--; return true; }
    public override int Remaining { get { return pending.Length - position; } }
    public override void Reset() { pending = ""; position = 0; base.Reset(); }
}

