internal static class Program {
    public static string VersionDisplay {
        get {
            var attribute=(System.Reflection.AssemblyInformationalVersionAttribute)System.Attribute.GetCustomAttribute(typeof(Program).Assembly,typeof(System.Reflection.AssemblyInformationalVersionAttribute));
            if(attribute!=null&&!String.IsNullOrWhiteSpace(attribute.InformationalVersion))return attribute.InformationalVersion;
            Version version=typeof(Program).Assembly.GetName().Version;
            return version==null?"v0.0.0":"v"+version.ToString();
        }
    }
    [STAThread] static void Main(string[] args) {
        Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false);
        string backup=null,database=null;
        if(args!=null)foreach(string arg in args){if(String.IsNullOrWhiteSpace(arg))continue;string extension=Path.GetExtension(arg);if(String.Equals(extension,".fbk",StringComparison.OrdinalIgnoreCase))backup=arg;else if(String.Equals(extension,".fdb",StringComparison.OrdinalIgnoreCase))database=arg;}
        MainForm form=new MainForm(backup,database);
        form.Shown += delegate { CleanupPreviousExecutable(); };
        Application.Run(form);
    }
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]
    static extern bool MoveFileEx(string existingFileName,string newFileName,int flags);
    static void CleanupPreviousExecutable() {
        Task.Run(delegate {
            string previous=Process.GetCurrentProcess().MainModule.FileName+".previous";
            for(int attempt=0;attempt<120;attempt++) {
                try {
                    if(!File.Exists(previous))return;
                    FileAttributes attributes=File.GetAttributes(previous);
                    if((attributes&FileAttributes.ReadOnly)!=0)File.SetAttributes(previous,attributes&~FileAttributes.ReadOnly);
                    File.Delete(previous);
                    if(!File.Exists(previous))return;
                } catch {}
                System.Threading.Thread.Sleep(1000);
            }
            try { if(File.Exists(previous))MoveFileEx(previous,null,4); } catch {}
        });
    }
}

