        details=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,WordWrap=true,BackColor=Color.FromArgb(243,244,246),Font=new Font("Consolas",8.5f)};details.Text="Aguardando o Firebird iniciar a operação...";root.Controls.Add(details,0,2);
