        foreach(string key in keyColumns){int index=-1;for(int c=0;c<previous.Columns.Count;c++)if(String.Equals(previous.Columns[c].ColumnName,key,StringComparison.OrdinalIgnoreCase)){index=c;break;}if(index<0){CompareRowsWithoutKeys(previous,current,removed,added);return;}indexes.Add(index);}
