        var matched=new bool[current.Rows.Count];
        foreach(DataRow oldRow in previous.Rows){string key=PrimaryKeyToken(oldRow,indexes,keyColumns);if(!currentByKey.ContainsKey(key)||currentByKey[key].Count==0){removed.Add(FormatPrimaryKey(oldRow,indexes,keyColumns));continue;}int newIndex=currentByKey[key].Dequeue();matched[newIndex]=true;changed.AddRange(GetFieldChanges(oldRow,current.Rows[newIndex],FormatPrimaryKey(oldRow,indexes,keyColumns)));}
