    static void CompareRowsWithoutKeys(DataTable previous,DataTable current,List<string> removed,List<MonitorNewRecord> added) { var currentCounts=RowCounts(current);foreach(DataRow row in previous.Rows){string key=RowKey(row);int count=currentCounts.ContainsKey(key)?currentCounts[key]:0;if(count>0)currentCounts[key]=count-1;else removed.Add("Chave primária ausente no SELECT");}var oldCounts=RowCounts(previous);foreach(DataRow row in current.Rows){string key=RowKey(row);int count=oldCounts.ContainsKey(key)?oldCounts[key]:0;if(count>0)oldCounts[key]=count-1;else added.Add(CreateNewRecord(row,"Chave primária ausente no SELECT"));} }
    static MonitorNewRecord CreateNewRecord(DataRow row,string key) { var detail=new StringBuilder();var summary=new StringBuilder();int included=0;foreach(DataColumn column in row.Table.Columns){string value=row.IsNull(column)?"<NULL>":FormatMonitorValue(column.ColumnName,Convert.ToString(row[column]));detail.Append(column.ColumnName).Append(" = ").AppendLine(value);if(included<4){if(summary.Length>0)summary.Append(" | ");string shortValue=value.Length>72?value.Substring(0,69)+"...":value;summary.Append(column.ColumnName).Append('=').Append(shortValue);included++;}}if(row.Table.Columns.Count>included)summary.Append(" | +").Append((row.Table.Columns.Count-included).ToString()).Append(" campo(s); duplo clique para ver tudo");return new MonitorNewRecord(key,summary.ToString(),detail.ToString()); }
    static List<MonitorFieldChange> GetFieldChanges(DataRow before,DataRow after,string key) { var changes=new List<MonitorFieldChange>();for(int i=0;i<before.Table.Columns.Count;i++){object oldValue=before[i],newValue=after[i];string oldText=oldValue==DBNull.Value?"<NULL>":Convert.ToString(oldValue),newText=newValue==DBNull.Value?"<NULL>":Convert.ToString(newValue);if(String.Equals(oldText,newText,StringComparison.Ordinal))continue;string field=before.Table.Columns[i].ColumnName;changes.Add(new MonitorFieldChange(key,field,FormatMonitorValue(field,oldText),FormatMonitorValue(field,newText)));}return changes; }
    static string FormatMonitorValue(string field,string value) {
        if(String.IsNullOrWhiteSpace(value)||value=="<NULL>")return value;
        string name=Regex.Replace(field??"","[^A-Za-z0-9]","").ToUpperInvariant();
        bool monetary=(name.StartsWith("VAL",StringComparison.Ordinal)&&!name.StartsWith("VALID",StringComparison.Ordinal))||name.StartsWith("VLR",StringComparison.Ordinal)||name.Contains("VALOR")||name.Contains("PAGO")||name.Contains("PAGAMENTO")||name.Contains("PRECO")||name.Contains("CUSTO")||name.Contains("TOTAL")||name.Contains("DESCONTO")||name.Contains("TROCO")||name.Contains("SALDO")||name.Contains("FRETE")||name.Contains("TARIFA")||name.Contains("LIQUIDO")||name.Contains("BRUTO");
        if(!monetary)return value;
        string number=value.Trim();int comma=number.LastIndexOf(',');int dot=number.LastIndexOf('.');
        if(comma>=0&&dot>=0){if(comma>dot)number=number.Replace(".","").Replace(',', '.');else number=number.Replace(",","");}
        else if(comma>=0)number=number.Replace(',', '.');
