    static string PrimaryKeyToken(DataRow row,List<int> indexes,List<string> names) { var key=new StringBuilder();for(int i=0;i<indexes.Count;i++){object item=row[indexes[i]];string value=item==null||item==DBNull.Value?null:Convert.ToString(item);key.Append(names[i].Length).Append(':').Append(names[i]).Append('|');if(value==null)key.Append("-1:");else key.Append(value.Length).Append(':').Append(value);key.Append('|');}return key.ToString(); }
    static string FormatPrimaryKey(DataRow row,List<int> indexes,List<string> names) { var text=new StringBuilder();for(int i=0;i<indexes.Count;i++){if(i>0)text.Append(", ");text.Append(names[i]).Append('=').Append(Convert.ToString(row[indexes[i]]));}return text.ToString(); }    static Dictionary<string,int> RowCounts(DataTable table) { var counts=new Dictionary<string,int>(StringComparer.Ordinal);foreach(DataRow row in table.Rows){string key=RowKey(row);if(!counts.ContainsKey(key))counts[key]=0;counts[key]++;}return counts; }
    static string RowKey(DataRow row) { var key=new StringBuilder();foreach(DataColumn column in row.Table.Columns){string name=column.ColumnName,value=row.IsNull(column)?null:Convert.ToString(row[column]);key.Append(name.Length).Append(':').Append(name).Append('|');if(value==null)key.Append("-1:");else key.Append(value.Length).Append(':').Append(value);key.Append('|');}return key.ToString(); }
    static string FormatRow(DataRow row) { var text=new StringBuilder();for(int i=0;i<row.Table.Columns.Count;i++){if(i>0)text.Append(Environment.NewLine);string value=row.IsNull(i)?"<NULL>":Convert.ToString(row[i]);text.Append(row.Table.Columns[i].ColumnName).Append(" = ").Append(value??"");}return text.ToString(); }
