                    report.AppendLine("<style>body{font:14px Segoe UI,Arial,sans-serif;color:#243447;margin:28px}h1{color:#174a70}.summary{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.card{background:#f1f5f9;border-left:4px solid #3979a8;padding:12px 16px;min-width:130px}table{width:100%;border-collapse:collapse;margin-top:14px;table-layout:fixed}th{background:#e8eef4;text-align:left}td,th{border:1px solid #d5dde5;padding:8px;vertical-align:top;overflow-wrap:anywhere;word-break:break-word}td:nth-child(5){background:#fff5cf;font-weight:bold}td:nth-child(6){background:#ffeded;color:#9b1c1c}td:nth-child(7){background:#e8f8ec;color:#146b31;font-weight:bold}tr:nth-child(even){filter:brightness(.99)}</style></head><body>");
                    report.AppendLine("<h1>Alterações detectadas</h1><p>Gerado em "+System.Net.WebUtility.HtmlEncode(generated)+" | Banco: "+System.Net.WebUtility.HtmlEncode(database)+" | Intervalo: "+interval.Value.ToString()+" segundo(s) | Status: "+state+"</p>");
                    report.AppendLine("<div class=\"summary\"><div class=\"card\"><b>Campos alterados</b><br>"+modified.ToString("N0")+"</div><div class=\"card\"><b>Registros novos</b><br>"+entered.ToString("N0")+"</div><div class=\"card\"><b>Registros removidos</b><br>"+exited.ToString("N0")+"</div><div class=\"card\"><b>Falhas</b><br>"+failures.ToString("N0")+"</div></div>");
                    report.AppendLine("<table><thead><tr><th>Data e hora</th><th>Consulta/tabela</th><th>Tipo</th><th>Chave do registro</th><th>Campo alterado</th><th>Valor anterior</th><th>Valor novo</th><th>Resumo do registro</th><th>Todos os campos</th></tr></thead><tbody>");
                    foreach(DataGridViewRow row in eventsGrid.Rows){report.Append("<tr>");for(int c=0;c<8;c++)report.Append("<td>").Append(System.Net.WebUtility.HtmlEncode(Convert.ToString(row.Cells[c].Value))).Append("</td>");string fullDetails=Convert.ToString(row.Tag);report.Append("<td>");if(!String.IsNullOrWhiteSpace(fullDetails))report.Append("<details><summary>Ver todos os campos</summary><pre>").Append(System.Net.WebUtility.HtmlEncode(fullDetails)).Append("</pre></details>");report.AppendLine("</td></tr>");}
                    if(eventsGrid.Rows.Count==0)report.AppendLine("<tr><td colspan=\"9\">Nenhuma alteração foi detectada no período.</td></tr>");report.AppendLine("</tbody></table></body></html>");
                } else {
                    report.AppendLine("ALTERAÇÕES DETECTADAS");report.AppendLine("Gerado em: "+generated);report.AppendLine("Banco: "+database);report.AppendLine("Status: "+state);report.AppendLine("Intervalo: "+interval.Value.ToString()+" segundo(s)");report.AppendLine("Campos alterados: "+modified.ToString("N0")+" | Registros novos: "+entered.ToString("N0")+" | Registros removidos: "+exited.ToString("N0")+" | Falhas: "+failures.ToString("N0"));report.AppendLine();
                    if(eventsGrid.Rows.Count==0)report.AppendLine("Nenhuma alteração foi detectada no período.");foreach(DataGridViewRow row in eventsGrid.Rows){report.AppendLine("["+Convert.ToString(row.Cells[0].Value)+"] "+Convert.ToString(row.Cells[2].Value)+" | "+Convert.ToString(row.Cells[1].Value)+" | Chave: "+Convert.ToString(row.Cells[3].Value));if(!String.IsNullOrWhiteSpace(Convert.ToString(row.Cells[4].Value)))report.AppendLine("  Campo: "+Convert.ToString(row.Cells[4].Value)+" | Anterior: "+Convert.ToString(row.Cells[5].Value)+" | Novo: "+Convert.ToString(row.Cells[6].Value));if(!String.IsNullOrWhiteSpace(Convert.ToString(row.Cells[7].Value)))report.AppendLine("  Resumo: "+Convert.ToString(row.Cells[7].Value));string fullDetails=Convert.ToString(row.Tag);if(!String.IsNullOrWhiteSpace(fullDetails)){report.AppendLine("  Dados completos do novo registro:");foreach(string line in fullDetails.Replace("\r","").Split('\n'))if(line.Length>0)report.AppendLine("    "+line);}}
                }
                File.WriteAllText(dialog.FileName,report.ToString(),new UTF8Encoding(true));MessageBox.Show(this,"O relatório do monitoramento foi salvo em:"+Environment.NewLine+dialog.FileName,"Relatório salvo",MessageBoxButtons.OK,MessageBoxIcon.Information);
            } catch(Exception ex){MessageBox.Show(this,"Não foi possível salvar o relatório. Confira se a pasta permite gravação e tente novamente."+Environment.NewLine+Environment.NewLine+ex.Message,"Não foi possível criar o relatório",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
        }
    }   void ShowMonitorDetails() { using(var form=new Form{Text="Detalhes do monitoramento",Width=800,Height=420,StartPosition=FormStartPosition.CenterParent}){var box=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Font=new Font("Consolas",9),Text=String.IsNullOrWhiteSpace(lastTechnicalDetails)?"Ainda não houve falha. O monitor executa o SQL do editor e compara os resultados.":lastTechnicalDetails};form.Controls.Add(box);form.ShowDialog(this);} }
