internal sealed class DatabaseObjectsForm : Form {
    readonly Func<int,string,string> loadDetails;
    readonly Func<int,string,string,string> saveObject;
    readonly Action<string> debugProcedure;
    readonly List<string>[] allNames=new List<string>[3];
    readonly ListBox[] lists=new ListBox[3];
