    readonly Button[] editButtons=new Button[3];
    readonly Button[] saveButtons=new Button[3];
    readonly Button[] cancelButtons=new Button[3];
    readonly string[] currentNames=new string[3];
    readonly string[] originalDefinitions=new string[3];
    bool[] loading=new bool[3];
    public DatabaseObjectsForm(List<string> views,List<string> procedures,List<string> generators,Func<int,string,string> detailLoader,Func<int,string,string,string> saveHandler,Action<string> debugHandler) {
        loadDetails=detailLoader;saveObject=saveHandler;debugProcedure=debugHandler;allNames[0]=views;allNames[1]=procedures;allNames[2]=generators;
        Text="Objetos do banco de dados";Icon=System.Drawing.Icon.ExtractAssociatedIcon(Application.ExecutablePath);Width=1000;Height=680;MinimumSize=new Size(760,500);StartPosition=FormStartPosition.CenterParent;
        var tabs=new TabControl{Dock=DockStyle.Fill};Controls.Add(tabs);
        AddObjectTab(tabs,"Views",0);AddObjectTab(tabs,"Procedures",1);AddObjectTab(tabs,"Generators",2);
    }
    void AddObjectTab(TabControl tabs,string title,int objectType) {
        var page=new TabPage(title);tabs.TabPages.Add(page);
        var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Vertical,FixedPanel=FixedPanel.Panel1};split.Size=new Size(950,600);split.SplitterDistance=280;page.Controls.Add(split);
        var left=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2,Padding=new Padding(5)};left.RowStyles.Add(new RowStyle(SizeType.AutoSize));left.RowStyles.Add(new RowStyle(SizeType.Percent,100));split.Panel1.Controls.Add(left);
