        string hint=objectType==2?"Valor atual do generator (edite o número para alterar):":"Definição SQL (use Editar para alterar):";right.Controls.Add(new Label{Text=hint,AutoSize=true,Padding=new Padding(2,3,2,6)},0,0);
        details[objectType]=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Font=new Font("Consolas",9),Text="Selecione um objeto para visualizar."};right.Controls.Add(details[objectType],0,1);
        var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,FlowDirection=FlowDirection.RightToLeft,WrapContents=false};cancelButtons[objectType]=new Button{Text="Cancelar",AutoSize=true,Enabled=false,Margin=new Padding(4)};saveButtons[objectType]=new Button{Text="Salvar alterações",AutoSize=true,Enabled=false,Margin=new Padding(4)};editButtons[objectType]=new Button{Text="Editar",AutoSize=true,Enabled=false,Margin=new Padding(4)};buttons.Controls.Add(cancelButtons[objectType]);buttons.Controls.Add(saveButtons[objectType]);buttons.Controls.Add(editButtons[objectType]);if(objectType==1){var debug=new Button{Text="Testar procedure",AutoSize=true,Margin=new Padding(4)};debug.Click+=(s,e)=>{if(!String.IsNullOrEmpty(currentNames[objectType])&&debugProcedure!=null)debugProcedure(currentNames[objectType]);};buttons.Controls.Add(debug);}right.Controls.Add(buttons,0,2);
        searches[objectType].TextChanged+=(s,e)=>FilterObjects(objectType);
        lists[objectType].SelectedIndexChanged+=(s,e)=>LoadSelectedObject(objectType);
        details[objectType].TextChanged+=(s,e)=>{if(loading[objectType])return;saveButtons[objectType].Enabled=!details[objectType].ReadOnly&&!String.Equals(details[objectType].Text,originalDefinitions[objectType],StringComparison.Ordinal);};
        editButtons[objectType].Click+=(s,e)=>BeginEdit(objectType);cancelButtons[objectType].Click+=(s,e)=>CancelEdit(objectType);saveButtons[objectType].Click+=(s,e)=>SaveEdit(objectType);
