    void FilterObjects(int objectType) {
        if(lists[objectType]==null)return;string filter=searches[objectType].Text.Trim(),selected=currentNames[objectType];loading[objectType]=true;lists[objectType].BeginUpdate();lists[objectType].Items.Clear();
