        if(selectedIndex>=0)lists[objectType].SelectedIndex=selectedIndex;else if(lists[objectType].Items.Count>0)lists[objectType].SelectedIndex=0;
        lists[objectType].EndUpdate();loading[objectType]=false;if(selectedIndex<0)LoadSelectedObject(objectType);
    }
    void LoadSelectedObject(int objectType) {
