        details[objectType].ReadOnly=true;editButtons[objectType].Enabled=!String.IsNullOrEmpty(currentNames[objectType]);saveButtons[objectType].Enabled=false;cancelButtons[objectType].Enabled=false;
        if(String.IsNullOrEmpty(currentNames[objectType])){originalDefinitions[objectType]="";details[objectType].Text="Nenhum objeto encontrado para esta pesquisa.";return;}
