    }
    void CancelEdit(int objectType) { details[objectType].ReadOnly=true;details[objectType].Text=originalDefinitions[objectType];editButtons[objectType].Enabled=!String.IsNullOrEmpty(currentNames[objectType]);saveButtons[objectType].Enabled=false;cancelButtons[objectType].Enabled=false; }
    void SaveEdit(int objectType) {
        if(String.Equals(originalDefinitions[objectType],details[objectType].Text,StringComparison.Ordinal))return;
        string kind=objectType==0?"view":objectType==1?"procedure":"generator";
        if(MessageBox.Show(this,"Salvar as alterações em "+kind+" '"+currentNames[objectType]+"'?\r\n\r\nA definição atual será substituída no banco de dados.","Confirmar alteração",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;
        string error=saveObject(objectType,currentNames[objectType],details[objectType].Text);
        if(!String.IsNullOrEmpty(error)){MessageBox.Show(this,"Não foi possível salvar a definição. Revise o SQL e confira os detalhes abaixo."+Environment.NewLine+Environment.NewLine+error,"Não foi possível salvar",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}
        MessageBox.Show(this,"A definição foi salva no banco de dados.","Alteração salva",MessageBoxButtons.OK,MessageBoxIcon.Information);LoadSelectedObject(objectType);
    }
