    string PasswordFilePath() { return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"consultasqlpass.ini"); }
    bool LoadPasswordFromFile() { string file=PasswordFilePath();if(!File.Exists(file))return false;try{Dictionary<string,object> root=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(file));object section;Dictionary<string,object> settings=root!=null&&root.TryGetValue("consultasql",out section)?section as Dictionary<string,object>:null;object value;if(settings==null||!settings.TryGetValue("pass",out value)||value==null){passBox.Clear();SetConnectionIndicator("● Desconectado",Color.DarkRed,Color.MistyRose);status.Text="O arquivo consultasqlpass.ini não contém um valor válido em consultasql.pass. Corrija o arquivo antes de conectar.";status.ForeColor=Color.DarkOrange;return false;}string password=Convert.ToString(value);if(String.IsNullOrEmpty(password)){passBox.Clear();SetConnectionIndicator("● Desconectado",Color.DarkRed,Color.MistyRose);status.Text="O campo consultasql.pass está vazio. Informe uma senha válida no arquivo antes de conectar.";status.ForeColor=Color.DarkOrange;return false;}passBox.Text=password;SetConnectionIndicator("● Desconectado",Color.DarkRed,Color.MistyRose);return true;}catch{passBox.Clear();SetConnectionIndicator("● Desconectado",Color.DarkRed,Color.MistyRose);status.Text="Não foi possível ler consultasqlpass.ini. Confira se o arquivo contém JSON válido.";status.ForeColor=Color.DarkOrange;return false;} }
    bool updateCheckStarted=false;
    async void CheckForUpdates() {
        if(updateCheckStarted||IsDisposed)return;updateCheckStarted=true;UpdateCandidate update=null;
        try { update=await Task.Run(delegate{return ConsultaSQLUpdater.CheckForUpdate();}); }
        catch(Exception ex) { ConsultaSQLUpdater.LastDiagnostic="Não foi possível verificar a atualização. Detalhe: "+ex.GetType().Name+": "+ex.Message; }
        if(IsDisposed)return;
        if(update==null)return;
        status.Text="Nova versão "+update.Tag+" encontrada. Atualizando e reiniciando o programa...";status.ForeColor=Color.DarkGreen;if(tips!=null)tips.SetToolTip(status,"O executável será baixado e o programa será reiniciado.");
        await Task.Delay(1500);if(IsDisposed)return;
        try { string[] command=Environment.GetCommandLineArgs();string[] restartArgs=new string[Math.Max(0,command.Length-1)];if(command.Length>1)Array.Copy(command,1,restartArgs,0,command.Length-1);ConsultaSQLUpdater.Start(update,Process.GetCurrentProcess().Id,restartArgs);SaveLastSession();Application.Exit(); }
        catch(Exception ex) { ShowExecutionError("A atualização foi encontrada, mas não foi possível reiniciar o programa.",ex.ToString(),"Feche o programa e tente novamente. Se ele estiver em uma pasta protegida, instale-o em uma pasta com permissão de gravação."); }
