    string LastSessionFile() { return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"ConsultaSQL","ultima-sessao.json"); }
    string lastUsedDatabase="", lastExecutedSql="";
    void LoadLastSession() {
        try { string file=LastSessionFile();if(File.Exists(file)){var values=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(file));if(values!=null){if(values.ContainsKey("database"))lastUsedDatabase=values["database"]??"";if(values.ContainsKey("sql"))lastExecutedSql=values["sql"]??"";}} }
        catch { lastUsedDatabase="";lastExecutedSql=""; }
        if(String.IsNullOrWhiteSpace(lastUsedDatabase)){LoadRecentDatabases();if(recentDatabases.Count>0)lastUsedDatabase=recentDatabases[0];}
        if(!String.IsNullOrWhiteSpace(lastUsedDatabase))dbBox.Text=lastUsedDatabase;
        if(!String.IsNullOrWhiteSpace(lastExecutedSql))sqlBox.Text=lastExecutedSql;
        SetConnectionIndicator("● Desconectado",Color.DarkRed,Color.MistyRose);
        status.Text=String.IsNullOrWhiteSpace(lastUsedDatabase)?"Para começar, selecione o arquivo do banco, informe a senha e clique em Conectar.":"Último banco selecionado. Informe a senha e clique em Conectar para continuar.";status.ForeColor=Color.DimGray;
    }
    void SaveLastSession() {
        try { if(String.IsNullOrWhiteSpace(lastUsedDatabase)&&String.IsNullOrWhiteSpace(lastExecutedSql))return;string file=LastSessionFile();Directory.CreateDirectory(Path.GetDirectoryName(file));var values=new Dictionary<string,string>();values["database"]=lastUsedDatabase??"";values["sql"]=lastExecutedSql??"";File.WriteAllText(file,new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue}.Serialize(values),new UTF8Encoding(false)); }
        catch { }
    }    void LoadRecentDatabases() { recentDatabases.Clear();string f=DatabaseListFile();if(!File.Exists(f))return;foreach(string line in File.ReadAllLines(f))if(!String.IsNullOrWhiteSpace(line)&&!recentDatabases.Exists(delegate(string x){return String.Equals(x,line,StringComparison.OrdinalIgnoreCase);}))recentDatabases.Add(line); }
