    void GenerateUpdateForSelectedRow(DataGridView g) { QueryResultState state=g==null?null:g.Tag as QueryResultState;if(g==null||g.CurrentRow==null||state==null||state.TableName.Length==0)return;if(!state.MetadataLoaded)LoadEditMetadata(state);if(state.PrimaryKey.Count==0){MessageBox.Show(this,"Para gerar um UPDATE seguro, o resultado precisa vir de uma tabela com chave primária ou índice único detectável.","Não é possível gerar UPDATE",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}try{var columns=new List<DataGridViewColumn>();foreach(DataGridViewColumn c in g.Columns)if(IsScriptColumn(state,c))columns.Add(c);var rows=new List<DataGridViewRow>{g.CurrentRow};Dictionary<string,string> blobs=PrepareBlobExpressions(rows,columns,state);var sets=new List<string>();foreach(DataGridViewColumn c in columns)if(!state.PrimaryKey.Exists(delegate(string k){return String.Equals(k,c.Name,StringComparison.OrdinalIgnoreCase);}))sets.Add(SqlIdentifier(c.Name)+" = "+SqlScriptValue(g.CurrentRow.Cells[c.Index].Value,state,c.Name,blobs));var where=new List<string>();foreach(string k in state.PrimaryKey){object v=g.CurrentRow.Cells[k].Value;where.Add(SqlIdentifier(k)+(v==null||v==DBNull.Value?" IS NULL":" = "+SqlLiteralForColumn(v,state,k)));}sqlBox.Text="UPDATE "+SqlIdentifier(state.TableName)+" SET "+String.Join(", ",sets.ToArray())+" WHERE "+String.Join(" AND ",where.ToArray())+";";sqlBox.Focus();}catch(Exception ex){MessageBox.Show(this,"Não foi possível gerar o UPDATE.\r\n\r\n"+ex.Message,"Falha ao gerar UPDATE",MessageBoxButtons.OK,MessageBoxIcon.Warning);} }
