    async void SearchDatabaseNames(TextBox searchBox,DataGridView results,Label hint,Button searchButton) {
        if(searchBox==null||results==null||hint==null||searchButton==null)return;string term=searchBox.Text.Trim();if(term.Length==0){hint.Text="Digite parte do nome da tabela ou do campo para pesquisar.";searchBox.Focus();return;}string escaped=term.Replace("'","''");string sql="SELECT CAST(CASE WHEN R.RDB$VIEW_BLR IS NULL THEN 'Tabela' ELSE 'View' END AS VARCHAR(10)) AS TIPO, TRIM(R.RDB$RELATION_NAME) AS TABELA, CAST('' AS VARCHAR(63)) AS CAMPO FROM RDB$RELATIONS R WHERE COALESCE(R.RDB$SYSTEM_FLAG,0)=0 AND R.RDB$RELATION_NAME CONTAINING '"+escaped+"' UNION ALL SELECT CAST('Campo' AS VARCHAR(10)) AS TIPO, TRIM(R.RDB$RELATION_NAME) AS TABELA, TRIM(RF.RDB$FIELD_NAME) AS CAMPO FROM RDB$RELATIONS R JOIN RDB$RELATION_FIELDS RF ON RF.RDB$RELATION_NAME=R.RDB$RELATION_NAME WHERE COALESCE(R.RDB$SYSTEM_FLAG,0)=0 AND RF.RDB$FIELD_NAME CONTAINING '"+escaped+"' ORDER BY 2, 1, 3;";string executable=IsqlPath();if(executable==null){hint.Text="Não foi localizado o isql.exe do Firebird.";return;}string database=dbBox.Text.Trim(),password=passBox.Text;searchButton.Enabled=false;hint.Text="Pesquisando no catálogo do banco...";
        try{Tuple<DataTable,string> found=await Task.Run(delegate{string diagnostic;DataTable data=RunSelectIsql(sql,executable,database,password,out diagnostic);return Tuple.Create(data,diagnostic);});if(results.IsDisposed)return;if(HasSqlError(found.Item2)){hint.Text="A pesquisa não foi concluída. Consulte Detalhes da execução para ver a mensagem do Firebird.";outputBox.Text=found.Item2;return;}results.DataSource=found.Item1;if(results.Columns.Contains("TIPO")){results.Columns["TIPO"].HeaderText="Tipo";results.Columns["TIPO"].FillWeight=22;}if(results.Columns.Contains("TABELA")){results.Columns["TABELA"].HeaderText="Tabela / view";results.Columns["TABELA"].FillWeight=40;}if(results.Columns.Contains("CAMPO")){results.Columns["CAMPO"].HeaderText="Campo";results.Columns["CAMPO"].FillWeight=38;}hint.Text=found.Item1.Rows.Count==0?"Nenhuma tabela ou campo corresponde a esse nome.":Quantity(found.Item1.Rows.Count,"resultado encontrado","resultados encontrados")+". Selecione uma linha para copiar ou inserir a referência no SQL.";}catch(Exception ex){if(!results.IsDisposed)hint.Text="Não foi possível pesquisar no banco: "+ex.Message;}finally{if(!searchButton.IsDisposed)searchButton.Enabled=true;}
