    List<string> ReadObjectNames(string sql) {
        string raw=RunIsql(sql);if(HasSqlError(raw))throw new Exception(raw);var names=new List<string>();
        foreach(var row in ParseListRows(raw))if(row.ContainsKey("OBJECT_NAME")){string name=row["OBJECT_NAME"].Trim();if(name.Length>0)names.Add(name);}
        return names;
    }
    void ShowDatabaseObjects() {
        if(!Ready())return;
