            List<string> views=ReadObjectNames("SELECT TRIM(RDB$RELATION_NAME) AS OBJECT_NAME FROM RDB$RELATIONS WHERE RDB$VIEW_SOURCE IS NOT NULL AND COALESCE(RDB$SYSTEM_FLAG,0)=0 ORDER BY RDB$RELATION_NAME;");
