    }
    sealed class ProcedureParameterInfo {
        public string Name;
        public int Type;
        public int FieldType;
        public int FieldSubType;
        public int FieldScale;
        public string TypeName { get { return FirebirdTypeName(FieldType,FieldSubType,FieldScale); } }
    }
    static string FirebirdTypeName(int type,int subType,int scale) {
        switch(type){case 7:return "SMALLINT";case 8:return "INTEGER";case 9:return "QUAD";case 10:return "FLOAT";case 11:return "D_FLOAT";case 12:return "DATE";case 13:return "TIME";case 14:return "CHAR";case 16:return subType==1?"NUMERIC (scale "+Math.Abs(scale)+")":subType==2?"DECIMAL (scale "+Math.Abs(scale)+")":"BIGINT";case 23:return "BOOLEAN";case 27:return "DOUBLE";case 35:return "TIMESTAMP";case 37:return "VARCHAR";case 261:return "BLOB";default:return "Firebird type "+type.ToString();}
    }
    string ProcedureParameterLiteral(string value,ProcedureParameterInfo parameter) {
        if(String.IsNullOrWhiteSpace(value))return "NULL";
        string trimmed=value.Trim();
        if(parameter.FieldType==14||parameter.FieldType==37||parameter.FieldType==261||parameter.FieldType==12||parameter.FieldType==13||parameter.FieldType==35)return "'"+trimmed.Replace("'","''")+"'";
        if(parameter.FieldType==23){if(String.Equals(trimmed,"TRUE",StringComparison.OrdinalIgnoreCase)||trimmed=="1")return "TRUE";if(String.Equals(trimmed,"FALSE",StringComparison.OrdinalIgnoreCase)||trimmed=="0")return "FALSE";throw new FormatException("O parâmetro "+parameter.Name+" aceita TRUE ou FALSE.");}
        if(parameter.FieldType==7||parameter.FieldType==8||parameter.FieldType==9||parameter.FieldType==10||parameter.FieldType==11||parameter.FieldType==16||parameter.FieldType==27){decimal number;if(!Decimal.TryParse(trimmed.Replace(',','.'),System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out number))throw new FormatException("Informe um número válido para o parâmetro "+parameter.Name+".");return number.ToString(System.Globalization.CultureInfo.InvariantCulture);}
        return "'"+trimmed.Replace("'","''")+"'";
    }
