    string SaveDatabaseObject(int objectType,string name,string editedText) {
        string sql;
        if(objectType==2){long value;if(!Int64.TryParse((editedText??"").Trim(),out value))return "Informe um valor inteiro válido para o generator.";sql="SET GENERATOR "+SqlIdentifier(name)+" TO "+value.ToString(System.Globalization.CultureInfo.InvariantCulture)+";";}
        else {
            sql=Regex.Replace(editedText??"",@"^\s*CREATE\s+(VIEW|PROCEDURE)\b","CREATE OR ALTER $1",RegexOptions.IgnoreCase);
            string expected=objectType==0?"VIEW":"PROCEDURE";Match declared=Regex.Match(sql,@"^\s*CREATE\s+(?:OR\s+ALTER\s+)?"+expected+@"\s+(?:""(?<quoted>(?:""""|[^""])+)""|(?<plain>[A-Za-z][A-Za-z0-9_$]*))",RegexOptions.IgnoreCase);
            if(!declared.Success)return "A definição precisa começar com CREATE VIEW/PROCEDURE ou CREATE OR ALTER VIEW/PROCEDURE.";
            string declaredName=declared.Groups["quoted"].Success?declared.Groups["quoted"].Value.Replace("\"\"","\""):declared.Groups["plain"].Value;
            if(!String.Equals(declaredName,name,StringComparison.OrdinalIgnoreCase))return "A definição deve continuar sendo do objeto selecionado: "+name+".";
            if(!sql.TrimEnd().EndsWith(";",StringComparison.Ordinal))sql=sql.TrimEnd()+";";
        }
        string output=RunIsql(sql);if(HasSqlError(output))return output;return null;
