    string RemoveFullLineSqlComments(string source) { var result=new StringBuilder();string[] lines=(source??"").Replace("\r\n","\n").Replace('\r','\n').Split('\n');foreach(string line in lines)if(!line.TrimStart().StartsWith("--",StringComparison.Ordinal))result.AppendLine(line);return result.ToString(); }
    string RunScriptFileProcess(string executable,string database,string password,string source,bool errorsOnlyAtEnd,CancellationToken cancellationToken,List<string> progressStatements) {
