            process.OutputDataReceived+=(sender,e)=>{if(e.Data==null)return;string echoed=e.Data.Trim();echoed=Regex.Replace(echoed,@"^(?:(?:SQL|CON)>\s*)+","",RegexOptions.IgnoreCase);if(nextProgressStatement<progressStarts.Count&&progressStarts[nextProgressStatement].Length>0&&echoed.StartsWith(progressStarts[nextProgressStatement],StringComparison.OrdinalIgnoreCase)){int activeStatement=++nextProgressStatement;ReportScriptProgress(activeStatement);}lock(outputLock)output.AppendLine(e.Data);if(!errorsOnlyAtEnd&&(e.Data.IndexOf("Statement failed",StringComparison.OrdinalIgnoreCase)>=0||e.Data.IndexOf("ERROR:",StringComparison.OrdinalIgnoreCase)>=0)){try{BeginInvoke((Action)delegate{if(!IsDisposed)MessageBox.Show(this,"Um erro ocorreu durante a execução do script. A execução continuará; consulte Detalhes da execução ao final.","Erro no script",MessageBoxButtons.OK,MessageBoxIcon.Warning);});}catch{}}};
