    string MaskSqlStringsAndComments(string text) {
        text=text??"";char[] masked=text.ToCharArray();foreach(Match match in Regex.Matches(text,@"'(?:''|[^'])*'|""(?:""""|[^""])*""|--[^\r\n]*|/\*[\s\S]*?\*/"))for(int i=match.Index;i<match.Index+match.Length;i++)if(masked[i]!='\r'&&masked[i]!='\n')masked[i]=' ';return new string(masked);
