            else if(missing.Count>0){message="Variável sem valor definido: :"+missing[0]+". Defina-a antes da consulta, por exemplo :"+missing[0]+"='21'.";foreground=Color.DarkRed;background=Color.MistyRose;}
            else if(definitions.Count>0){var parts=new List<string>();foreach(var item in definitions){parts.Add(":"+item.Key+" = "+item.Value);if(parts.Count>=3)break;}message="Variáveis SQL: "+String.Join("; ",parts.ToArray())+". Os valores serão substituídos antes da execução.";}
        }
