    void CenterGridCell(DataGridView g,int row,int column) {
        if(g==null||row<0||column<0||row>=g.Rows.Count||column>=g.Columns.Count)return;
        try {
            int visibleRows=Math.Max(1,g.DisplayedRowCount(false));
            int firstRow=Math.Max(0,row-visibleRows/2);
            firstRow=Math.Min(firstRow,Math.Max(0,g.Rows.Count-visibleRows));
            if(!g.Rows[firstRow].Frozen)g.FirstDisplayedScrollingRowIndex=firstRow;
        } catch {}
        try {
            List<DataGridViewColumn> scrollable=new List<DataGridViewColumn>();
            for(int i=0;i<g.Columns.Count;i++)if(g.Columns[i].Visible&&!g.Columns[i].Frozen)scrollable.Add(g.Columns[i]);
            int target=scrollable.FindIndex(delegate(DataGridViewColumn item){return item.Index==column;});
            if(target<0||scrollable.Count==0)return;
            int visibleColumns=Math.Max(1,g.DisplayedColumnCount(false));
            int first=Math.Max(0,target-visibleColumns/2);
            first=Math.Min(first,Math.Max(0,scrollable.Count-visibleColumns));
            g.FirstDisplayedScrollingColumnIndex=scrollable[first].Index;
        } catch {}
    }
    void HighlightSearchColumn(DataGridView g,int column) {
        foreach(QueryResultState state in queryStates)if(state.Grid!=null){state.SearchHighlightColumn=-1;state.Grid.Invalidate();}
        QueryResultState current=g==null?null:g.Tag as QueryResultState;
        if(current!=null&&column>=0&&column<g.Columns.Count){current.SearchHighlightColumn=column;g.Invalidate();}
    }
