        int total=rowCount*columns;int startIndex=g.CurrentCell==null?0:g.CurrentCell.RowIndex*columns+g.CurrentCell.ColumnIndex+1;
        for(int i=0;i<total;i++){int flat=(startIndex+i)%total;int r=flat/columns,c=flat%columns;object value=view[r][g.Columns[c].DataPropertyName];if(Convert.ToString(value).IndexOf(lastSearch,StringComparison.OrdinalIgnoreCase)>=0){g.CurrentCell=g.Rows[r].Cells[c];g.ClearSelection();g.Rows[r].Cells[c].Selected=true;HighlightSearchColumn(g,c);CenterGridCell(g,r,c);CloseCellTextSelection();g.Focus();status.Text="Texto encontrado na grade: linha "+(r+1).ToString()+", campo "+g.Columns[c].HeaderText+".";status.ForeColor=Color.DarkGreen;return;}}
