    void FormatSql(bool selected) { int start=selected?sqlBox.SelectionStart:0,length=selected?sqlBox.SelectionLength:sqlBox.Text.Length;if(length==0)return;string t=sqlBox.Text.Substring(start,length);t=Regex.Replace(t,@"\s+(SELECT|FROM|WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|INNER\s+JOIN|UNION|UPDATE|SET|VALUES|INSERT\s+INTO|DELETE\s+FROM)\b",Environment.NewLine+"$1",RegexOptions.IgnoreCase);t=Regex.Replace(t,@"\b(SELECT|FROM|WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|INNER\s+JOIN|UNION|UPDATE|SET|VALUES|INSERT\s+INTO|DELETE\s+FROM)\b",delegate(Match m){return m.Value.ToUpperInvariant();},RegexOptions.IgnoreCase);sqlBox.Select(start,length);sqlBox.SelectedText=t;sqlBox.Focus(); }
