    List<string> GetBlobIds(IEnumerable<DataGridViewRow> rows,List<DataGridViewColumn> columns,QueryResultState state) { var ids=new List<string>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(DataGridViewRow row in rows){if(row==null||row.IsNewRow)continue;foreach(DataGridViewColumn column in columns){int type;if(!state.FieldTypes.TryGetValue(column.Name,out type)||type!=261)continue;object value=row.Cells[column.Index].Value;if(value==null||value==DBNull.Value||String.Equals(Convert.ToString(value).Trim(),"<null>",StringComparison.OrdinalIgnoreCase))continue;string id=Convert.ToString(value).Trim();if(!Regex.IsMatch(id,@"^[0-9A-Fa-f]+:[0-9A-Fa-f]+$"))throw new InvalidOperationException("O Firebird não forneceu o identificador do BLOB no campo "+column.Name+". Execute novamente a consulta e tente gerar o script.");if(seen.Add(id))ids.Add(id);}}return ids; }
    Dictionary<string,byte[]> DumpBlobValues(IEnumerable<string> blobIds,string exe,string database,string password) { var files=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var values=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);foreach(string id in blobIds){if(!files.ContainsKey(id))files[id]=Path.Combine(Path.GetTempPath(),"CSQL_"+Guid.NewGuid().ToString("N")+".blob");}if(files.Count==0)return values;if(String.IsNullOrWhiteSpace(exe)||!File.Exists(exe))throw new InvalidOperationException("Não foi localizado o isql.exe necessário para ler os campos BLOB.");try{var psi=new ProcessStartInfo{FileName=exe,Arguments="-q -ch UTF8",WorkingDirectory=Path.GetDirectoryName(exe),UseShellExecute=false,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true,StandardOutputEncoding=FirebirdOutputText.Encoding,StandardErrorEncoding=FirebirdOutputText.Encoding};ClearInheritedFirebirdCredentials(psi);using(var p=new Process{StartInfo=psi}){if(!p.Start())throw new InvalidOperationException("Não foi possível iniciar o isql.exe para ler os BLOBs.");Task<string> stdout=p.StandardOutput.ReadToEndAsync(),stderr=p.StandardError.ReadToEndAsync();string db=FirebirdConnectionTarget(database).Replace("'","''"),pw=(password??"").Replace("'","''");p.StandardInput.WriteLine("CONNECT '"+db+"' USER 'SYSDBA' PASSWORD '"+pw+"';");p.StandardInput.WriteLine("SET BLOB;");foreach(var pair in files)p.StandardInput.WriteLine("BLOBDUMP "+pair.Key+" \""+pair.Value.Replace("\"","\"\"")+"\";");p.StandardInput.WriteLine("QUIT;");p.StandardInput.Close();p.WaitForExit();string output=stdout.Result+Environment.NewLine+stderr.Result;foreach(var pair in files){if(!File.Exists(pair.Value))throw new InvalidOperationException("Não foi possível ler o conteúdo completo do BLOB "+pair.Key+".\r\n\r\n"+output.Trim());values[pair.Key]=File.ReadAllBytes(pair.Value);}}return values;}finally{foreach(string file in files.Values)try{if(File.Exist