    Encoding GetBlobEncoding(QueryResultState state,string column) { string charset="";if(state!=null)state.FieldCharacterSets.TryGetValue(column??"",out charset);string name=(charset??"").Replace("_","").Replace("-","").ToUpperInvariant();try{if(name=="UTF8")return new UTF8Encoding(false,true);if(name=="WIN1252"||name=="WINDOWS1252")return Encoding.GetEncoding(1252);if(name=="ISO88591")return Encoding.GetEncoding(28591);if(name=="DOS437")return Encoding.GetEncoding(437);if(name=="DOS850")return Encoding.GetEncoding(850);if(name=="ASCII")return Encoding.ASCII;if(name=="OCTETS")return Encoding.Default;if(name.Length>0&&name!="NONE")return Encoding.GetEncoding(charset);}catch{}return Encoding.Default; }
    string BuildBlobSqlExpression(byte[] bytes,QueryResultState state,string column) { int subtype=0;if(state!=null)state.FieldSubTypes.TryGetValue(column??"",out subtype);if(subtype==1){string text=GetBlobEncoding(state,column).GetString(bytes);return BuildTextBlobSqlExpression(text,"TEXT CHARACTER SET UTF8");}if(subtype!=0)throw new InvalidOperationException("O subtipo "+subtype.ToString()+" do campo BLOB "+column+" não pode ser exportado como SQL com segurança. Exporte o conteúdo bruto pelo visualizador do BLOB.");if(bytes.Length==0)return "CAST(X'' AS BLOB SUB_TYPE BINARY)";var binary=new List<string>();for(int offset=0;offset<bytes.Length;offset+=8000){int count=Math.Min(8000,bytes.Length-offset);var hex=new StringBuilder(count*2);for(int i=0;i<count;i++)hex.Append(bytes[offset+i].ToString("X2"));binary.Add("CAST(X'"+hex.ToString()+"' AS BLOB SUB_TYPE BINARY)");}return String.Join(" || ",binary.ToArray()); }
    string BuildTextBlobSqlExpression(string text,string subtype) { if(String.IsNullOrEmpty(text))return "CAST(_UTF8 '' AS BLOB SUB_TYPE "+subtype+")";var parts=new List<string>();for(int offset=0;offset<text.Length;){int count=Math.Min(2000,text.Length-offset);if(offset+count<text.Length&&count>0&&Char.IsHighSurrogate(text[offset+count-1])&&Char.IsLowSurrogate(text[offset+count]))count--;string chunk=text.Substring(offset,count);parts.Add("CAST(_UTF8 '"+chunk.Replace("'","''")+"' AS BLOB SUB_TYPE "+subtype+")");offset+=count;}return String.Join(" || ",parts.ToArray()); }
    Dictionary<string,string> PrepareBlobExpressions(IEnumerable<DataGridViewRow> rows,List<DataGridViewColumn> columns,QueryResultState state) { var ids=GetBlobIds(rows,columns,state);if(ids.Count==0)return new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);string exe=IsqlPath();if(String.IsNullOrWhiteSpace(exe))throw new InvalidOperationException("Geração cancelada: não foi localizado o isql.exe para ler os BLOBs.");Dictionary<string,byte[]> data=DumpBlobValues(ids,exe,dbBox.Text,passBox.Text);var expressions=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string id in ids){byte[] bytes;if(!data.TryGetValue(id,out bytes))throw new InvalidOperationException("O conteúdo do BLOB "+id+" não foi carregado.");string field="";foreach(DataGridViewColumn column in columns){int type;if(state.FieldTypes.TryGetValue(column.Name,out type)&&type==261){foreach(DataGridViewRow row in rows){if(row==null||row.IsNewRow)continue;if(String.Equals(Convert.ToString(row.Cells[column.Index].Value).Trim(),id,StringComparison.OrdinalIgnoreCase)){field=column.Name;break;}}if(field.Length>0)break;}}expressions[id]=BuildBlobSqlExpression(bytes,state,field);}return expressions; }
    string SqlScriptValue(object value,QueryResultState state,string column,Dictionary<string,string> blobExpressions) { int type;if(value!=null&&value!=DBNull.Value&&state!=null&&state.FieldTypes.TryGetValue(column??"",out type)&&type==261&&!String.Equals(Convert.ToString(value).Trim(),"<null>",StringComparison.OrdinalIgnoreCase)){string expression;if(blobExpressions==null||!blobExpressions.TryGetValue(Convert.ToString(value).Trim(),out expression))throw new InvalidOperationException("Não encontrei o conteúdo BLOB de "+column+" para incluir no script.");return expression;}return SqlLiteralForColumn(value,state,column); }
    void GenerateInsertForSelectedRow(DataGridView g) { QueryResultState state=g==null?null:g.Tag as QueryResultState;if(g==null||g.CurrentRow==null||state==null||state.TableName.Length==0)return;if(!state.MetadataLoaded)LoadEditMetadata(state);var cols=new List<string>();var values=new List<DataGridViewColumn>();foreach(DataGridViewColumn c in g.Columns)if(IsScriptColumn(state,c)){cols.Add(SqlIdentifier(c.Name));values.Add(c);}if(cols.Count==0){MessageBox.Show(this,"Não encontrei campos válidos da tabela para gerar o INSERT.","INSERT indisponível",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}try{var rows=new List<DataGridViewRow>{g.CurrentRow};Dictionary<string,string> blobs=PrepareBlobExpressions(rows,values,state);var vals=new List<string>();foreach(DataGridViewColumn c in values)vals.Add(SqlScriptValue(g.CurrentRow.Cells[c.Index].Value,state,c.Name,blobs));sqlBox.Text="INSERT INTO "+SqlIdentifier(state.TableName)+" ("+String.Join(", ",cols.ToArray())+")\r\nVALUES ("+String.Join(", ",vals.ToArray())+");";sqlBox.Focus();}catch(Exception ex){MessageBox.Show(this,"Não foi possível gerar o INSERT.\r\n\r\n"+ex.Message,"Falha ao gerar INSERT",MessageBoxButtons.OK,MessageBoxIcon.Warning);} }
    void GenerateBatchSql(DataGridView g,bool insert) {
        QueryResultState state=g==null?null:g.Tag as QueryResultState;if(state==null||String.IsNullOrWhiteSpace(state.TableName)){MessageBox.Show(this,"Não foi possível identificar a tabela deste resultado.","Gerar script",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}
        if(inlineCellEditor!=null&&Object.ReferenceEquals(inlineCellEditorGrid,g))CloseInlineCellEditor(true);
        if(g.Rows.Count==0){MessageBox.Show(this,"O resultado está vazio. Execute uma consulta que retorne registros antes de gerar o script.","Nenhum registro no resultado",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}
        var keyIndexes=new List<int>();if(!insert){if(!state.MetadataLoaded)LoadEditMetadata(state);if(state.PrimaryKey.Count==0){MessageBox.Show(this,"Não foi possível gerar UPDATE em lote: a tabela precisa ter uma chave primária ou índice único detectável.","UPDATE indisponível",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}foreach(string key in state.PrimaryKey){int idx=-1;for(int i=0;i<g.Columns.Count;i++)if(String.Equals(g.Columns[i].Name,key,StringComparison.OrdinalIgnoreCase)){idx=i;break;}if(idx<0){MessageBox.Show(this,"A coluna da chave primária '"+key+"' não está no resultado. Use SELECT * FROM "+state.TableName+" para gerar os UPDATEs.","UPDATE indisponível",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}keyIndexes.Add(idx);}}
        if(!state.MetadataLoaded)LoadEditMetadata(state);string action=insert?"INSERT":"UPDATE";string safeName=Regex.Replace(state.TableName,@"[^A-Za-z0-9_-]","_");
        string exportTimestamp=DateTime.Now.ToString("yyyyMMdd_HHmmss",System.Globalization.CultureInfo.InvariantCulture);using(var dialog=new SaveFileDialog{Title="Salvar script "+action+" em lote",Filter="Script SQL (*.sql)|*.sql|Texto (*.txt)|*.txt",DefaultExt="sql",AddExtension=true,FileName=safeName+"_"+action.ToLowerInvariant()+"_todos_"+exportTimestamp+".sql"}){
            if(dialog.ShowDialog(this)!=DialogResult.OK)return;int generated=0;status.Text="Gerando script "+action+" para " + g.Rows.Count.ToString("N0")+" registros...";status.ForeColor=Color.DarkOrange;status.Refresh();
            try{using(var writer=new StreamWriter(dialog.FileName,false,Encoding.GetEncoding(1252))){writer.WriteLine("-- Script "+action+" gerado pelo ConsultaSQL para "+g.Rows.Count.ToString()+" registro(s).");writer.WriteLine("-- Exportado em: "+DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss",System.Globalization.CultureInfo.InvariantCulture));writer.WriteLine("-- Revise o arquivo antes de executar.");writer.WriteLine();
                var visibleColumns=new List<DataGridViewColumn>();var cols=new List<string>();foreach(DataGridViewColumn c in g.Columns)if(IsScriptColumn(state,c)){visibleColumns.Add(c);cols.Add(SqlIdentifier(c.Name));}if(visibleColumns.Count==0)throw new InvalidOperationException("Não encontrei campos válidos da tabela para gerar o script.");var batchRows=new List<DataGridViewRow>();foreach(DataGridViewRow row in g.Rows)if(!row.IsNewRow)batchRows.Add(row);Dictionary<string,string> blobExpressions=PrepareBlobExpressions(batchRows,visibleColumns,state);
                foreach(DataGridViewRow row in batchRows){
                    if(insert){var vals=new List<string>();foreach(DataGridViewColumn c in visibleColumns){object v=row.Cells[c.Index].Value;vals.Add(SqlScriptValue(v,state,c.Name,blobExpressions));}writer.WriteLine("INSERT INTO "+SqlIdentifier(state.TableName)+" ("+String.Join(", ",cols.ToArray())+")");writer.WriteLine("VALUES ("+String.Join(", ",vals.ToArray())+");");writer.WriteLine();}
                    else{var sets=new List<string>();foreach(DataGridViewColumn c in visibleColumns){if(keyIndexes.Contains(c.Index))continue;object v=row.Cells[c.Index].Value;sets.Add(SqlIdentifier(c.Name)+" = "+SqlScriptValue(v,state,c.Name,blobExpressions));}if(sets.Count==0)continue;var where=new List<string>();for(int i=0;i<state.PrimaryKey.Count;i++){object v=row.Cells[keyIndexes[i]].Value;where.Add(SqlIdentifier(state.PrimaryKey[i])+(v==null||v==DBNull.Value?" IS NULL":" = "+SqlLiteralForColumn(v,state,state.PrimaryKey[i])));}writer.WriteLine("UPDATE "+SqlIdentifier(state.TableName)+" SET "+String.Join(", ",sets.ToArray())+" WHERE "+String.Join(" AND ",where.ToArray())+";");}
                    generated++;
                }
            }status.Text="Arquivo SQL salvo com "+generated.ToString("N0")+" comando(s): "+dialog.FileName;status.ForeColor=Color.DarkGreen;MessageBox.Show(this,"Arquivo SQL criado e salvo com sucesso.\r\n\r\nTipo: "+action+"\r\nComandos gerados: "+generated.ToString("N0")+"\r\nLocal do arquivo:\r\n"+dialog.FileName+"\r\n\r\nOs comandos estão no arquivo e ainda não foram executados no banco. Os conteúdos BLOB foram incluídos no SQL.","Arquivo SQL salvo",MessageBoxButtons.OK,MessageBoxIcon.Information);
            }catch(Exception ex){status.Text="Falha ao gerar o script em lote.";status.ForeColor=Color.DarkRed;MessageBox.Show(this,"Não foi possível criar o arquivo SQL.\r\n\r\n"+ex.Message,"Falha ao gerar script",MessageBoxButtons.OK,MessageBoxIcon.Error);}
        }
    }    void AddExport(FlowLayoutPanel p,string label,string ext) { var b=new Button { Text=label, AutoSize=true, Margin=new Padding(6) }; b.Click += (s,e)=>Export(ext); p.Controls.Add(b); }
    void ChooseDatabase() { using(var d=new OpenFileDialog { Title="Selecione o banco Firebird", Filter="Bancos Firebird (*.fdb;*.gdb)|*.fdb;*.gdb|Todos os arquivos (*.*)|*.*", CheckFileExists=true }) if(d.ShowDialog(this)==DialogResult.OK) dbBox.Text=d.FileName; }
    void OpenDatabaseMonitor() {
        if(!Ready())return;
        string monitoredSql,variableError;if(!PrepareSqlVariables(sqlBox.Text,out monitoredSql,out variableError)){MessageBox.Show(this,variableError,"Revise as variáveis SQL",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}List<string> statements=SplitStatements(monitoredSql);
        if(statements.Count==0){MessageBox.Show(this,"Digite ao menos uma consulta SELECT no editor SQL para iniciar o monitoramento.","Consulta necessária",MessageBoxButtons.OK,MessageBoxIcon.Information);sqlBox.Focus();return;}
        var queries=new List<Tuple<string,string>>();
        for(int i=0;i<statements.Count;i++){
            string statement=statements[i];
            if(!IsSelectStatement(statement)){MessageBox.Show(this,"O monitoramento executa somente consultas SELECT. Remova INSERT, UPDATE, DELETE ou outros comandos e tente novamente.","Use somente consultas SELECT",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}
            string name=GetSimpleTableName(statement);if(String.IsNullOrWhiteSpace(name))name=GetSingleTableSourceName(statement);if(String.IsNullOrWhiteSpace(name))name="Consulta "+(i+1).ToString();
            queries.Add(Tuple.Create(name,statement));
        }
        string exe=IsqlPath();if(exe==null)return;
        using(var form=new DatabaseMonitorForm(exe,dbBox.Text.Trim(),passBox.Text,queries))form.ShowDialog(this);
    }    string IsqlPath() { string p=Path.Combine(firebirdBin,"isql.exe"); if(File.Exists(p)) return p; using(var d=new OpenFileDialog { Title="Localize o isql.exe do Firebird", Filter="isql.exe|isql.exe|Executáveis (*.exe)|*.exe", CheckFileExists=true }) { if(d.ShowDialog(this)==DialogResult.OK){firebirdBin=Path.GetDirectoryName(d.FileName); return d.FileName;} } return null; }
    bool Ready() { if(String.IsNullOrWhiteSpace(dbBox.Text)){status.Text="Informe o caminho do arquivo do banco Firebird.";status.ForeColor=Color.DarkRed;dbBox.Focus();return false;} if(String.IsNullOrEmpty(passBox.Text)){status.Text="Informe a senha do usuário SYSDBA.";status.ForeColor=Color.DarkRed;passBox.Focus();return false;} return true; }
    string GbakPath() { string p=Path.Combine(firebirdBin,"gbak.exe"); if(File.Exists(p))return p; using(var d=new OpenFileDialog { Title="Localize o gbak.exe do Firebird", Filter="gbak.exe|gbak.exe|Executáveis (*.exe)|*.exe", CheckFileExists=true }) { if(d.ShowDialog(this)==DialogResult.OK){firebirdBin=Path.GetDirectoryName(d.FileName);return d.FileName;} } return null; }
    string QuoteArg(string value) { return "\""+value.Replace("\"","\\\"")+"\""; }
    string RunGbak(string exe,string arguments,Action<string> progress) {
        if(String.IsNullOrWhiteSpace(exe)||!File.Exists(exe))throw new Exception("Não foi possível localizar o gbak.exe do Firebird.");string passwordFile=Path.Combine(Path.GetTempPath(),"ConsultaSQL-"+Guid.NewGuid().ToString("N")+".pwd");
        try { File.WriteAllText(passwordFile,passBox.Text,Encoding.Default);var psi=new ProcessStartInfo{FileName=exe,Arguments=arguments+" -user SYSDBA -fetch_password "+QuoteArg(passwordFile),WorkingDirectory=Path.GetDirectoryName(exe),UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true,StandardOutputEncoding=FirebirdOutputText.Encoding,StandardErrorEncoding=FirebirdOutputText.Encoding};ClearInheritedFirebirdCredentials(psi);var output=new StringBuilder();var outputLock=new object();using(var p=new Process{StartInfo=psi,EnableRaisingEvents=true}){p.OutputDataReceived+=(s,e)=>{if(e.Data!=null){lock(outputLock)output.AppendLine(e.Data);if(progress!=null)progress(e.Data);}};p.ErrorDataReceived+=(s,e)=>{if(e.Data!=null){lock(outputLock)output.AppendLine(e.Data);if(progress!=null)progress(e.Data);}};if(!p.Start())throw new Exception("Não foi possível iniciar o gbak.exe.");p.BeginOutputReadLine();p.BeginErrorReadLine();p.WaitForExit();p.WaitForExit();string result;lock(outputLock)result=output.ToString();if(p.ExitCode!=0)throw new Exception(String.IsNullOrWhiteSpace(result)?"O gbak.exe encerrou com erro (código "+p.ExitCode.ToString()+").":result);return result;}}
        finally { try { if(File.Exists(passwordFile))File.Delete(passwordFile); } catch {} }
    }
    async Task<string> RunGbakWithProgress(string exe,string arguments,string title,string initialMessage) {
        using(var dialog=new GbakProgressForm(title,initialMessage))using(var poll=new System.Windows.Forms.Timer{Interval=150}) {
            Task<string> operation=Task.Run(delegate{return RunGbak(exe,arguments,dialog.Report);});poll.Tick+=(s,e)=>{if(operation.IsCompleted){poll.Stop();if(!dialog.IsDisposed)dialog.DialogResult=DialogResult.OK;}};poll.Start();dialog.ShowDialog(this);poll.Stop();return await operation;
        }
    }
    async void BackupDatabase() {
        if(!Ready())return; string gbak=GbakPath(); if(gbak==null)return;
        string baseName=Path.GetFileNameWithoutExtension(dbBox.Text.Trim()); if(String.IsNullOrWhiteSpace(baseName))baseName="backup"; foreach(char c in Path.GetInvalidFileNameChars())baseName=baseName.Replace(c,'_');
        string suggestedBackupName=baseName+"_"+DateTime.Now.ToString("yyyyMMdd")+".fbk";
        using(var d=new SaveFileDialog { Title="Salvar backup Firebird", Filter="Backup Firebird (*.fbk)|*.fbk|Todos os arquivos (*.*)|*.*", DefaultExt="fbk", AddExtension=true, FileName=suggestedBackupName, OverwritePrompt=true }) {
            if(d.ShowDialog(this)!=DialogResult.OK)return;
            try { await RunGbakWithProgress(gbak,"-b "+QuoteArg(FirebirdConnectionTarget(dbBox.Text.Trim()))+" "+QuoteArg(d.FileName)+" -v","Fazendo backup","O Firebird está criando o backup. O tempo depende do tamanho do banco."); status.Text="Backup concluído: "+d.FileName; status.ForeColor=Color.DarkGreen; MessageBox.Show(this,"Backup concluído com sucesso.\r\n\r\nArquivo salvo em:\r\n"+d.FileName,"Backup concluído",MessageBoxButtons.OK,MessageBoxIcon.Information); }
            catch(Exception ex){outputBox.Text=ex.ToString();status.Text=FriendlyError(ex.Message,"O backup não foi concluído.");status.ForeColor=Color.DarkRed;resultTabs.SelectedIndex=1;MessageBox.Show(this,status.Text+"\r\n\r\nVeja Detalhes da execução para a mensagem completa.","Falha no backup",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
        }
    }
    async void RestoreDatabase() {
        if(String.IsNullOrEmpty(passBox.Text)){status.Text="Informe a senha do SYSDBA antes de restaurar o backup.";status.ForeColor=Color.DarkRed;passBox.Focus();return;}
        string backupFile;using(var open=new OpenFileDialog { Title="Selecione o arquivo de backup", Filter="Backup Firebird (*.fbk;*.gbk)|*.fbk;*.gbk|Todos os arquivos (*.*)|*.*", CheckFileExists=true }) { if(open.ShowDialog(this)!=DialogResult.OK)return;backupFile=open.FileName; }
        await RestoreBackupFile(backupFile);
    }
    async void HandleStartupBackup(string backupFile) {
        if(IsDisposed||String.IsNullOrWhiteSpace(backupFile))return;
        if(!File.Exists(backupFile)){MessageBox.Show(this,"O arquivo de backup não foi encontrado:\r\n\r\n"+backupFile,"Backup não encontrado",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}
        if(MessageBox.Show(this,"Você abriu este arquivo de backup:\r\n\r\n"+backupFile+"\r\n\r\nDeseja restaurá-lo agora? A restauração criará um novo arquivo de banco de dados.","Restaurar backup Firebird",MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;
        using(var prompt=new BackupPasswordForm(backupFile)){if(prompt.ShowDialog(this)!=DialogResult.OK)return;if(String.IsNullOrWhiteSpace(prompt.Password)){MessageBox.Show(this,"Informe a senha do usuário SYSDBA para continuar.","Senha necessária",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}passBox.Text=prompt.Password;}
        await RestoreBackupFile(backupFile);
    }
    async Task RestoreBackupFile(string backupFile) {
        if(String.IsNullOrEmpty(passBox.Text)){status.Text="Informe a senha do SYSDBA antes de restaurar o backup.";status.ForeColor=Color.DarkRed;passBox.Focus();return;}
        string gbak=GbakPath();if(gbak==null)return;
        string defaultName=Path.GetFileNameWithoutExtension(backupFile)+"_restaurado_"+DateTime.Now.ToString("yyyyMMdd")+".fdb";
        using(var save=new SaveFileDialog { Title="Escolha onde criar o banco restaurado", Filter="Banco Firebird (*.fdb)|*.fdb|Todos os arquivos (*.*)|*.*", DefaultExt="fdb", AddExtension=true, FileName=defaultName, OverwritePrompt=false }) {
            if(save.ShowDialog(this)!=DialogResult.OK)return;
            if(File.Exists(save.FileName)){MessageBox.Show(this,"Já existe um arquivo neste destino. Escolha outro caminho para preservar o banco atual.","Escolha outro destino",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}
            if(MessageBox.Show(this,"O backup será restaurado em um novo arquivo.\r\n\r\nBackup: "+backupFile+"\r\nNovo banco: "+save.FileName+"\r\n\r\nDeseja continuar?","Confirmar restauração",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)!=DialogResult.OK)return;
            try { await RunGbakWithProgress(gbak,"-c "+QuoteArg(backupFile)+" "+QuoteArg(FirebirdConnectionTarget(save.FileName))+" -v","Restaurando banco de dados","O Firebird está restaurando o backup no arquivo escolhido.");dbBox.Text=save.FileName;status.Text="Banco restaurado. Conecte-se ao novo arquivo para começar a usá-lo.";status.ForeColor=Color.DarkGreen;MessageBox.Show(this,"Restauração concluída.\r\n\r\nO novo banco foi criado em:\r\n"+save.FileName+"\r\n\r\nConecte-se a esse arquivo para começar a usá-lo.","Restauração concluída",MessageBoxButtons.OK,MessageBoxIcon.Information);}
            catch(Exception ex){outputBox.Text=ex.ToString();status.Text=FriendlyError(ex.Message,"A restauração não foi concluída.");status.ForeColor=Color.DarkRed;resultTabs.SelectedIndex=1;MessageBox.Show(this,status.Text+"\r\n\r\nVeja Detalhes da execução para a mensagem completa.","Falha na restauração",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
        }
    }
    static void ClearInheritedFirebirdCredentials(ProcessStartInfo psi) { if(psi==null)return;var environment=psi.EnvironmentVariables;if(environment==null)return;environment.Remove("ISC_USER");environment.Remove("ISC_PASSWORD"); }
