    void CancelRunningQuery() { if(queryCancellation==null||queryCancellation.IsCancellationRequested)return;status.Text="Interrompendo a execução...";status.ForeColor=Color.DarkOrange;if(cancelExecutionButton!=null)cancelExecutionButton.Enabled=false;queryCancellation.Cancel(); }
