    void BeginScriptProgress(int totalCommands,bool canCountCommands) { if(scriptProgressFooter==null)return;scriptProgressCommandCount=Math.Max(1,totalCommands);scriptProgressBar.Minimum=0;scriptProgressBar.Maximum=scriptProgressCommandCount;scriptProgressBar.Value=0;scriptProgressBar.Style=canCountCommands&&scriptProgressCommandCount>1?ProgressBarStyle.Blocks:ProgressBarStyle.Marquee;scriptProgressLabel.Text=canCountCommands?"Executando script: 0 de "+scriptProgressCommandCount.ToString()+" comandos":"Executando bloco SQL...";scriptProgressFooter.Visible=true;scriptProgressFooter.BringToFront(); }
