    void SetConnectionIndicator(string text,Color foreground,Color background) { if(String.Equals(text,"● Conectado",StringComparison.OrdinalIgnoreCase))connectionValidated=true;else if(text.StartsWith("● Sem conexão",StringComparison.OrdinalIgnoreCase)||text.StartsWith("● Desconectado",StringComparison.OrdinalIgnoreCase))connectionValidated=false; if(connectButton!=null)connectButton.Text=connectionValidated?"Desconectar":"Conectar"; if(connectionIndicator==null)return; connectionIndicator.Text="●"; connectionIndicator.ForeColor=foreground; connectionIndicator.BackColor=background;if(tips!=null)tips.SetToolTip(connectionIndicator,text); }
