    string FriendlyError(string detail,string fallback) {
        string e=detail??"";
        if(e.IndexOf("identificador da linha não foi encontrado",StringComparison.OrdinalIgnoreCase)>=0)return "O Firebird não localizou a linha desta edição. Nenhuma alteração foi gravada; atualize a consulta e tente novamente.";
        if(e.IndexOf("O registro não corresponde mais aos valores originais",StringComparison.OrdinalIgnoreCase)>=0||e.IndexOf("Records affected: 0",StringComparison.OrdinalIgnoreCase)>=0)return "Nenhuma alteração foi gravada porque a linha mudou desde a consulta. Atualize os dados e tente editar novamente.";
        if(e.IndexOf("Os valores identificam ",StringComparison.OrdinalIgnoreCase)>=0)return "Não foi possível salvar com segurança porque os valores correspondem a mais de uma linha. A atualização foi cancelada.";
        if(e.IndexOf("password",StringComparison.OrdinalIgnoreCase)>=0 || e.IndexOf("user name",StringComparison.OrdinalIgnoreCase)>=0 || e.IndexOf("authentication",StringComparison.OrdinalIgnoreCase)>=0)return "Não foi possível entrar. Confira a senha do SYSDBA.";
        if(e.IndexOf("unavailable database",StringComparison.OrdinalIgnoreCase)>=0 || e.IndexOf("I/O error",StringComparison.OrdinalIgnoreCase)>=0 || e.IndexOf("CreateFile",StringComparison.OrdinalIgnoreCase)>=0)return "Não foi possível abrir o banco. Confira o caminho, se o arquivo existe e se você tem acesso a ele.";
        if(e.IndexOf("Table unknown",StringComparison.OrdinalIgnoreCase)>=0)return "A tabela não foi encontrada neste banco. Confira o nome e o banco selecionado.";
        if(e.IndexOf("Column unknown",StringComparison.OrdinalIgnoreCase)>=0)return "Uma coluna da consulta não foi encontrada. Confira os nomes dos campos.";
        if(e.IndexOf("Token unknown",StringComparison.OrdinalIgnoreCase)>=0 || e.IndexOf("SQL error code = -104",StringComparison.OrdinalIgnoreCase)>=0)return "O Firebird não reconheceu parte do SQL. Revise a consulta e tente novamente.";
        if(e.IndexOf("violation of PRIMARY or UNIQUE KEY constraint",StringComparison.OrdinalIgnoreCase)>=0)return "Este registro já existe. Confira a chave primária ou os campos que precisam ter valores únicos.";
        if(e.IndexOf("FOREIGN KEY",StringComparison.OrdinalIgnoreCase)>=0)return "Esta alteração depende de outro registro. Confira se o registro relacionado existe antes de tentar novamente.";
        if(e.IndexOf("arithmetic exception",StringComparison.OrdinalIgnoreCase)>=0 || e.IndexOf("numeric overflow",StringComparison.OrdinalIgnoreCase)>=0)return "Um valor excede o formato permitido pelo campo. Confira o número e a quantidade de casas decimais.";
        if(e.IndexOf("read-only",StringComparison.OrdinalIgnoreCase)>=0 || e.IndexOf("read only",StringComparison.OrdinalIgnoreCase)>=0)return "O banco ou o campo está somente para leitura. Confira as permissões e o modo de acesso.";
        if(e.IndexOf("Statement failed",StringComparison.OrdinalIgnoreCase)>=0)return "O Firebird recusou o comando. Clique em Detalhes para ver a mensagem completa.";
        return fallback;
    }
    void ShowExecutionDetails() { using(var f=new Form{Text="Detalhes da execução",Width=850,Height=520,StartPosition=FormStartPosition.CenterParent}){var box=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Font=new Font("Consolas",9),Text=outputBox==null?"":outputBox.Text};f.Controls.Add(box);f.ShowDialog(this);} }
    void ShowExecutionError(string title,string detail,string fallback) {
        string message=FriendlyError(detail,fallback); status.Text=message; status.ForeColor=Color.DarkRed; resultTabs.SelectedIndex=1;
        if(!String.IsNullOrWhiteSpace(detail))outputBox.Text=detail;
        MessageBox.Show(this,message+Environment.NewLine+Environment.NewLine+"Clique em Detalhes para consultar a mensagem técnica do Firebird.",title,MessageBoxButtons.OK,MessageBoxIcon.Warning);
    }
    void Connect() {
