        if(bytes.Length>=4&&Encoding.ASCII.GetString(bytes,0,4)=="%PDF"){kind="Documento PDF";extension="pdf";return;}
        if(bytes.Length>=4&&bytes[0]==0x50&&bytes[1]==0x4B){kind="Arquivo ZIP ou documento Office";extension="zip";return;}
        if(bytes.Length>=5&&Encoding.ASCII.GetString(bytes,0,5)=="{\\rtf"){kind="Documento RTF";extension="rtf";return;}
        if(bytes.Length>=12&&Encoding.ASCII.GetString(bytes,0,4)=="RIFF"&&Encoding.ASCII.GetString(bytes,8,4)=="WAVE"){kind="Áudio WAV";extension="wav";return;}
