        foreach(DataGridViewColumn c in activeState.Grid.Columns){c.ReadOnly=c.Name.StartsWith("CS_INTERNAL_",StringComparison.OrdinalIgnoreCase)||c.Name.StartsWith("CS_BLOB_OPEN_",StringComparison.OrdinalIgnoreCase)||activeState.ReadOnlyColumns.Exists(delegate(string x){return String.Equals(x,c.Name,StringComparison.OrdinalIgnoreCase);});if(!c.ReadOnly)hasEditableColumn=true;}
        if(!hasEditableColumn){activeState.Grid.ReadOnly=true;activeState.Grid.EditMode=DataGridViewEditMode.EditOnKeystrokeOrF2;activeState.Editing=false;editMode=false;MessageBox.Show(this,"Todos os campos retornados pelo Firebird são somente leitura. Confira se a tabela permite alterações e se a consulta inclui as colunas da tabela.","Campos somente leitura",MessageBoxButtons.OK,MessageBoxIcon.Information);ActivateResult(activeState);return;}
        saveButton.Enabled=true;saveButton.Visible=true;cancelButton.Enabled=true;cancelButton.Visible=true;editButton.Enabled=false;editButton.Visible=false;status.Text=activeState.UseOriginalValuesAsIdentity?"Modo de edição ativo sem chave única. Ao salvar, só será gravado se os valores antigos identificarem uma linha." : "Modo de edição ativo. Edite uma célula e pressione Enter; depois escolha Salvar para gravar ou Cancelar para desfazer.";status.ForeColor=Color.DarkOrange;
        activeState.Grid.Focus();DataGridViewCell cell=activeState.Grid.CurrentCell;if(cell==null&&activeState.Grid.Rows.Count>0&&activeState.Grid.Columns.Count>0)cell=activeState.Grid.Rows[0].Cells[0];if(cell!=null&&cell.ReadOnly){for(int r=0;r<activeState.Grid.Rows.Count&&cell.ReadOnly;r++)for(int c=0;c<activeState.Grid.Columns.Count;c++)if(!activeState.Grid.Rows[r].Cells[c].ReadOnly){cell=activeState.Grid.Rows[r].Cells[c];break;}}if(cell!=null)BeginGridCellEdit(activeState.Grid,cell);
    }    void CancelEdits() {
