    void AppendStreamedRows(DataTable table,List<Dictionary<string,string>> batch) { if(table==null||batch==null||batch.Count==0)return;table.BeginLoadData();try{foreach(Dictionary<string,string> values in batch){DataRow row=table.NewRow();foreach(var pair in values)if(table.Columns.Contains(pair.Key))row[pair.Key]=pair.Value??"";table.Rows.Add(row);}}finally{table.EndLoadData();} }
    List<DataColumn> VisibleResultColumns() { var columns=new List<DataColumn>();foreach(DataColumn c in resultTable.Columns)if(!String.Equals(c.ColumnName,DbKeyLocatorColumn,StringComparison.OrdinalIgnoreCase)&&!c.ColumnName.StartsWith("CS_INTERNAL_DB_KEY",StringComparison.OrdinalIgnoreCase))columns.Add(c);return columns; }
    void Export(string ext) { if(resultTable.Rows.Count==0 && ext!="txt"){MessageBox.Show(this,"Não há registros para exportar. Execute um SELECT e selecione o resultado desejado.","Nenhum resultado para exportar",MessageBoxButtons.OK,MessageBoxIcon.Information);return;} string filter=ext=="html"?"Página HTML (*.html)|*.html":ext=="json"?"Arquivo JSON (*.json)|*.json":ext=="csv"?"Arquivo CSV (*.csv)|*.csv":ext=="xml"?"Arquivo XML (*.xml)|*.xml":"Texto (*.txt)|*.txt";string exportTimestamp=DateTime.Now.ToString("yyyyMMdd_HHmmss",System.Globalization.CultureInfo.InvariantCulture);using(var d=new SaveFileDialog { Title="Exportar resultado da consulta",Filter=filter, FileName="resultado_"+exportTimestamp+"."+ext, AddExtension=true, DefaultExt=ext }) { if(d.ShowDialog(this)!=DialogResult.OK)return; try { string content; if(ext=="txt")content=TextResult(); else if(ext=="csv")content=CsvResult(); else if(ext=="xml")content=XmlResult(); else if(ext=="json"){var columns=VisibleResultColumns();var list=new List<Dictionary<string,string>>();foreach(DataRow row in resultTable.Rows){var item=new Dictionary<string,string>();foreach(DataColumn c in columns)item[c.ColumnName]=row[c]==DBNull.Value?null:FormatExportValue(row[c],activeState,c.ColumnName);list.Add(item);}content=new JavaScriptSerializer { MaxJsonLength=Int32.MaxValue }.Serialize(list);} else content=HtmlResult(); File.WriteAllText(d.FileName,content,new UTF8Encoding(true)); status.Text="Resultado exportado para: "+d.FileName;status.ForeColor=Color.DarkGreen;AskOpenExportedFile(d.FileName); } catch(Exception ex){status.Text="Não foi possível exportar o resultado. Confira o caminho e as permissões da pasta.";status.ForeColor=Color.DarkRed;MessageBox.Show(this,status.Text+Environment.NewLine+Environment.NewLine+ex.Message,"Falha na exportação",MessageBoxButtons.OK,MessageBoxIcon.Error);} } }
    string TextResult() { if(resultTable.Rows.Count==0)return outputBox.Text;var columns=VisibleResultColumns();var b=new StringBuilder();for(int i=0;i<columns.Count;i++){if(i>0)b.Append((char)9);b.Append(columns[i].ColumnName);}b.AppendLine();foreach(DataRow r in resultTable.Rows){for(int i=0;i<columns.Count;i++){if(i>0)b.Append((char)9);b.Append(FormatExportValue(r[columns[i]],activeState,columns[i].ColumnName));}b.AppendLine();}return b.ToString(); }
    string CsvResult() { var columns=VisibleResultColumns();var b=new StringBuilder();for(int i=0;i<columns.Count;i++){if(i>0)b.Append(';');b.Append(CsvValue(columns[i].ColumnName));}b.AppendLine();foreach(DataRow r in resultTable.Rows){for(int i=0;i<columns.Count;i++){if(i>0)b.Append(';');b.Append(CsvValue(FormatExportValue(r[columns[i]],activeState,columns[i].ColumnName)));}b.AppendLine();}return b.ToString(); }
    string CsvValue(string value) { return "\""+(value??"").Replace("\"","\"\"")+"\""; }
    string XmlResult() { DataTable export=resultTable.Copy();for(int i=export.Columns.Count-1;i>=0;i--)if(String.Equals(export.Columns[i].ColumnName,DbKeyLocatorColumn,StringComparison.OrdinalIgnoreCase)||export.Columns[i].ColumnName.StartsWith("CS_INTERNAL_DB_KEY",StringComparison.OrdinalIgnoreCase))export.Columns.RemoveAt(i);foreach(DataRow row in export.Rows)foreach(DataColumn column in export.Columns)row[column]=FormatExportValue(row[column],activeState,column.ColumnName);using(var writer=new StringWriter()){export.WriteXml(writer,XmlWriteMode.IgnoreSchema);return writer.ToString();} }
    string HtmlResult() {
        var columns=VisibleResultColumns();List<DataGridViewColumn> gridColumns=new List<DataGridViewColumn>();if(activeState!=null&&activeState.Grid!=null)foreach(DataGridViewColumn column in activeState.Grid.Columns)if(column.Visible&&!column.Name.StartsWith("CS_BLOB_OPEN_",StringComparison.OrdinalIgnoreCase)&&!column.Name.StartsWith("CS_INTERNAL_",StringComparison.OrdinalIgnoreCase))gridColumns.Add(column);
        Dictionary<string,byte[]> blobs=gridColumns.Count>0?LoadBlobExportBytes(activeState.Grid,gridColumns,activeState):new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);string tableName=activeState==null?"Resultado":(String.IsNullOrWhiteSpace(activeState.TableName)?"Resultado":activeState.TableName);string sql=activeState==null?"":Regex.Replace(activeState.Sql??"",@"\s+"," ").Trim();
        var b=new StringBuilder("<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Resultado SQL</title><style>body{font:14px Segoe UI,Arial,sans-serif;color:#243447;margin:20px;background:#fff}h1{font-size:22px;margin:0 0 8px}p{color:#526273;margin:6px 0 12px}.table-wrap{overflow:auto;max-height:78vh;border:1px solid #d7dfe7}table{border-collapse:collapse;width:max-content;min-width:100%;table-layout:auto;font-size:13px}th,td{border:1px solid #cbd5df;padding:5px 8px;text-align:left;vertical-align:top;max-width:260px;overflow-wrap:anywhere}th{background:#e8eef4;position:sticky;top:0;z-index:1}tr:nth-child(even){background:#f5f7f9}.cell-value{max-height:42px;overflow:auto;white-space:nowrap;text-overflow:ellipsis}.long-value summary,.blob-text summary,.blob-image summary{cursor:pointer;color:#175d8c;font-weight:600}.long-value pre,.blob-text pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:340px;overflow:auto;background:#f5f7f9;border:1px solid #d8e0e8;border-radius:4px;padding:8px;font:12px Consolas,monospace}.blob-image img{display:block;max-width:560px;max-height:360px;object-fit:contain;margin:8px 0;background:#fff;border:1px solid #d8e0e8}.blob-binary{color:#536273;font-style:italic}code{white-space:normal;overflow-wrap:anywhere;background:#f4f6f8;padding:2px 4px}</style></head><body><h1>");b.Append(System.Net.WebUtility.HtmlEncode(tableName)).Append("</h1>");if(sql.Length>0)b.Append("<p><strong>SQL:</strong> <code>").Append(System.Net.WebUtility.HtmlEncode(sql)).Append("</code></p>");b.Append("<div class=\"table-wrap\"><table><thead><tr>");foreach(DataColumn c in columns)b.Append("<th>").Append(System.Net.WebUtility.HtmlEncode(c.ColumnName)).Append("</th>");b.Append("</tr></thead><tbody>");
        foreach(DataRow row in resultTable.Rows){b.Append("<tr>");foreach(DataColumn c in columns){DataGridViewColumn gridColumn=activeState!=null&&activeState.Grid!=null&&activeState.Grid.Columns.Contains(c.ColumnName)?activeState.Grid.Columns[c.ColumnName]:null;int type;if(gridColumn!=null&&activeState.FieldTypes.TryGetValue(c.ColumnName,out type)&&type==261)b.Append("<td>").Append(BlobHtmlCell(row[c],gridColumn,activeState,blobs)).Append("</td>");else b.Append("<td>").Append(CompactHtmlCell(FormatExportValue(row[c],activeState,c.ColumnName))).Append("</td>");}b.Append("</tr>");}
        return ApplyCompactExportStyles(b.Append("</tbody></table></div></body></html>").ToString());
    }
    void GenerateSql() { using(var f=new GeneratorForm())if(f.ShowDialog(this)==DialogResult.OK){sqlBox.Text=f.Generated;}
    }
}

internal sealed class GeneratorForm : Form {
    TextBox table,where,fields; RadioButton update,insert; public string Generated="";
    public GeneratorForm(){Text="Gerar SQL UPDATE / INSERT";Width=660;Height=560;MinimumSize=new Size(550,450);StartPosition=FormStartPosition.CenterParent;
        var p=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),ColumnCount=2,RowCount=5};p.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,130));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));p.RowStyles.Add(new RowStyle(SizeType.AutoSize));p.RowStyles.Add(new RowStyle(SizeType.AutoSize));p.RowStyles.Add(new RowStyle(SizeType.AutoSize));p.RowStyles.Add(new RowStyle(SizeType.Percent,100));p.RowStyles.Add(new RowStyle(SizeType.AutoSize));Controls.Add(p);
        var radios=new FlowLayoutPanel{AutoSize=true};update=new RadioButton{Text="UPDATE",Checked=true,AutoSize=true};insert=new RadioButton{Text="INSERT",AutoSize=true};radios.Controls.Add(update);radios.Controls.Add(insert);p.Controls.Add(new Label{Text="Tipo:",AutoSize=true,Anchor=AnchorStyles.Left},0,0);p.Controls.Add(radios,1,0);
        table=new TextBox{Dock=DockStyle.Top};p.Controls.Add(new Label{Text="Tabela:",AutoSize=true,Anchor=AnchorStyles.Left},0,1);p.Controls.Add(table,1,1);
        where=new TextBox{Dock=DockStyle.Top};p.Controls.Add(new Label{Text="WHERE (UPDATE):",AutoSize=true,Anchor=AnchorStyles.Left},0,2);p.Controls.Add(where,1,2);
        fields=new TextBox{Dock=DockStyle.Fill,Multiline=true,AcceptsReturn=true,AcceptsTab=true,ScrollBars=ScrollBars.Vertical,Font=new Font("Consolas",10),Text="CAMPO = valor"};p.Controls.Add(new Label{Text="Valores SQL:\r\nUma linha por campo.\r\nTexto entre aspas simples.\r\nEx.: NOME = 'Maria'\r\nEx.: ATIVO = 1",AutoSize=true,Anchor=AnchorStyles.Top},0,3);p.Controls.Add(fields,1,3);
        var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,AutoSize=true};var ok=new Button{Text="Gerar no editor",DialogResult=DialogResult.OK,AutoSize=true};ok.Click+=(s,e)=>Build();var cancel=new Button{Text="Cancelar",DialogResult=DialogResult.Cancel,AutoSize=true};buttons.Controls.Add(ok);buttons.Controls.Add(cancel);p.Controls.Add(buttons,0,4);p.SetColumnSpan(buttons,2);AcceptButton=ok;CancelButton=cancel;
        insert.CheckedChanged+=(s,e)=>{where.Enabled=!insert.Checked;};
    }
    void Build(){string t=table.Text.Trim();if(t.Length==0){MessageBox.Show(this,"Informe o nome da tabela que receberá o comando.","Tabela obrigatória",MessageBoxButtons.OK,MessageBoxIcon.Information);table.Focus();DialogResult=DialogResult.None;return;}var lines=new List<string>();foreach(string raw in fields.Text.Replace("\r","").Split('\n')){string l=raw.Trim().TrimEnd(',');if(l.Length>0&&l!="CAMPO = valor")lines.Add(l);}if(lines.Count==0){MessageBox.Show(this,"Informe ao menos um campo e seu valor. Use uma linha para cada campo.","Campos obrigatórios",MessageBoxButtons.OK,MessageBoxIcon.Information);fields.Focus();DialogResult=DialogResult.None;return;}
        if(insert.Checked){var cols=new List<string>();var vals=new List<string>();foreach(string l in lines){int i=l.IndexOf('=');if(i<1){MessageBox.Show(this,"Revise esta linha:\r\n"+l+"\r\n\r\nUse o formato CAMPO = valor.","Formato de campo inválido",MessageBoxButtons.OK,MessageBoxIcon.Warning);DialogResult=DialogResult.None;return;}cols.Add(l.Substring(0,i).Trim());vals.Add(l.Substring(i+1).Trim());}Generated="INSERT INTO "+t+" ("+String.Join(", ",cols.ToArray())+")\r\nVALUES ("+String.Join(", ",vals.ToArray())+");";}
        else{string w=where.Text.Trim();if(w.Length==0){MessageBox.Show(this,"Informe uma condição WHERE para indicar quais registros serão atualizados. Sem ela, o UPDATE poderia alterar a tabela inteira.","Condição WHERE obrigatória",MessageBoxButtons.OK,MessageBoxIcon.Warning);where.Focus();DialogResult=DialogResult.None;return;}Generated="UPDATE "+t+"\r\nSET "+String.Join(",\r\n    ",lines.ToArray())+"\r\nWHERE "+w+";";} DialogResult=DialogResult.OK;Close();
    }
}





